-- =====================================================================
-- VoucherFlow — update 9: recognise the company from the voucher number
-- Paste into Supabase → SQL Editor → new snippet → Run. Safe to run again.
--
-- Vouchers are printed in books of consecutive numbers, so the nearest known voucher
-- number almost always belongs to the same company. Loaded from the London voucher sheet
-- (53,659 plain-number vouchers, stored as 10461 number ranges), and it keeps learning
-- from every voucher you validate.
-- =====================================================================

create table if not exists public.company_number_ranges (
  id          bigint generated always as identity primary key,
  company_id  uuid not null references public.companies on delete cascade,
  start_no    bigint not null,
  end_no      bigint not null,
  vouchers    integer not null default 1,
  source      text not null default 'validated'
);
create index if not exists cnr_start_idx on public.company_number_ranges (start_no);
create index if not exists cnr_end_idx on public.company_number_ranges (end_no);

-- Number patterns (length + first digits) that mostly belong to one company — used when no
-- voucher is close enough.
create table if not exists public.company_number_patterns (
  len         integer not null,
  prefix      text not null,
  company_id  uuid not null references public.companies on delete cascade,
  share       numeric not null,
  primary key (len, prefix)
);

alter table public.company_number_ranges enable row level security;
alter table public.company_number_patterns enable row level security;
drop policy if exists "read number ranges" on public.company_number_ranges;
create policy "read number ranges" on public.company_number_ranges for select to authenticated using (public.my_role() is not null);
drop policy if exists "read number patterns" on public.company_number_patterns;
create policy "read number patterns" on public.company_number_patterns for select to authenticated using (public.my_role() is not null);

-- What the number history and the AI said about a voucher's company (shown while it's pending).
alter table public.vouchers add column if not exists company_hint jsonb;

-- Suggests a company for a plain voucher number: nearest known voucher (within ±p_range),
-- otherwise the number pattern. No suggestion if the nearest vouchers belong to different companies.
create or replace function public.suggest_company(p_voucher text, p_range int default 50)
returns table (company_id uuid, method text, from_voucher bigint, distance bigint)
language sql stable set search_path = public as $$
  with t as (
    select case when p_voucher ~ '^\d{4,18}$' then p_voucher::bigint end as n
  ),
  near as (
    select r.company_id,
           case when t.n between r.start_no and r.end_no then 0
                when t.n < r.start_no then r.start_no - t.n
                else t.n - r.end_no end as d,
           case when t.n < r.start_no then r.start_no
                when t.n > r.end_no then r.end_no
                else t.n end as from_no
    from public.company_number_ranges r, t
    where t.n is not null
      and r.start_no <= t.n + p_range
      and r.end_no >= t.n - p_range
  ),
  best as (select min(d) as d from near),
  nearest as (
    select n.company_id, 'nearest'::text as method, n.from_no as from_voucher, n.d as distance
    from near n, best b
    where n.d = b.d
      and (select count(distinct n2.company_id) from near n2 where n2.d = b.d) = 1
    limit 1
  ),
  pattern as (
    select p.company_id, 'pattern'::text, null::bigint, null::bigint
    from public.company_number_patterns p, t
    where t.n is not null
      and p.len = length(t.n::text)
      and left(t.n::text, length(p.prefix)) = p.prefix
    order by length(p.prefix) desc
    limit 1
  )
  select * from nearest
  union all
  select * from pattern where not exists (select 1 from nearest)
  limit 1
$$;
grant execute on function public.suggest_company(text, int) to authenticated;

-- Every validated plain-number voucher teaches the system its company.
create or replace function public.learn_company_number()
returns trigger language plpgsql security definer set search_path = public as $$
declare n bigint;
begin
  if new.company_id is not null
     and new.voucher_number ~ '^\d{4,18}$'
     and new.status not in ('pending', 'cancelled')
     and new.deleted_at is null then
    n := new.voucher_number::bigint;
    if not exists (select 1 from public.company_number_ranges r
                    where r.company_id = new.company_id and n between r.start_no and r.end_no) then
      insert into public.company_number_ranges (company_id, start_no, end_no, vouchers, source)
      values (new.company_id, n, n, 1, 'validated');
    end if;
  end if;
  return new;
end $$;

drop trigger if exists vouchers_learn_company_number on public.vouchers;
create trigger vouchers_learn_company_number
  after insert or update on public.vouchers
  for each row execute function public.learn_company_number();

